#include "tests/support/socket/native_dispatch_test_fixture.hpp"
using namespace dispatch_test;
namespace {
std::size_t index(const Effects& e,std::string_view name){const auto at=std::find(e.trace.begin(),e.trace.end(),name);check(at!=e.trace.end(),"required effect present");return at-e.trace.begin();}
void reject(Fixture& f){try{f.run();throw std::runtime_error("missing invalid message");}catch(const core_test::Failure& e){check(e.code==66,"native invalid terminal");}}
void commands(){for(const auto registration:m::registrations_032d00()){Fixture f;f.parse(request(registration.name));auto& out=f.run();check(&out==&f.native.locals.temporary&&f.effects.effects.commands==std::vector<std::uint32_t>{registration.rva},"all39 exact command names invoke registered RVA");check(f.output()==native_message_test::response("alpha")&&f.effects.outputs==1&&f.effects.destroyed==1,"independent complete response bytes and normal cleanup");check(index(f.effects,"registry")<index(f.effects,"document")&&index(f.effects,"output")<index(f.effects,"free-scratch")&&index(f.effects,"free-scratch")<index(f.effects,"destroy-printer"),"native init and publish/cleanup order");}}
void shapes(){for(const auto& xml:{std::string{},std::string("<bad/>"),std::string("<LSX/>"),std::string("<LSX><bad/></LSX>"),std::string("<LSX><Request id=\"a\" recipient=\"b\"><GetConfig/></Request><Request/></LSX>"),request("GetConfig","recipient=\"fixture\""),request("GetConfig","id=\"bridge\""),std::string("<LSX><Request id=\"a\" recipient=\"b\"/></LSX>"),request("getconfig"),request("Unknown")}){Fixture f;f.parse(xml);reject(f);check(f.effects.prepared==1&&!f.effects.constructed&&!f.effects.outputs,"invalid shapes rejected after registry but before printer/output");}
    {Fixture f;f.parse(request("GetConfig","id=\"\" recipient=\"\""));f.run();check(f.output().find("id=\"\" sender=\"\"")!=std::string::npos,"present empty attributes accepted");}
    {Fixture f;f.parse("<LSX><Request id=\"bridge\" recipient=\"fixture\"><GetConfig/><Unknown/></Request></LSX>");f.run();check(f.effects.handled==1,"command siblings ignored");}
    for(unsigned n:{16U,4096U}){Fixture f;f.parse(request(std::string(n,'Z')));reject(f);check(index(f.effects,"free")<index(f.effects,"invalid")&&!f.native.core.containers.f.m.response.live_blocks(),"long unknown name free precedes invalid including aligned heap");}
}
void live(){
    {Fixture f;f.parse(request("GetConfig"));f.effects.hook=[&](auto name){if(name=="attribute-sender")f.effects.entries[0].handler_rva=0x12345;};f.run();check(f.effects.effects.commands==std::vector<std::uint32_t>{0x12345},"handler token reloaded after printer callbacks");}
    {Fixture f;f.parse(request("ChallengeResponse"));f.effects.sentinel.handler_rva=0x54321;f.effects.hook=[&](auto name){if(name=="attribute-sender")f.effects.end=&f.effects.other_end;};f.run();check(!f.effects.challenges&&f.effects.effects.commands==std::vector<std::uint32_t>{0x54321},"live sentinel comparison after printer callbacks");}
    {Fixture f;f.parse(request("GetConfig"));f.effects.override_data=std::string("first\0tail\0",11);f.effects.override_size=11;f.effects.hook=[&](auto name){if(name=="reserve")f.effects.override_data=std::string("second\0abc\0",11);if(name=="output")check(f.effects.text(f.locals.scratch)==std::string("second\0abc",10),"discarded append uses freshly reloaded buffer");if(name=="append")f.effects.override_data=std::string("third\0last\0",11);};f.run();check(f.output()=="third"&&f.effects.reserved==54&&f.effects.appended==10,"output reloaded separately and strlen truncates embedded NUL");}
    for(std::int32_t count:{-1,0}){Fixture f;f.parse(request("GetConfig"));f.effects.override_size=count;f.effects.symbolic=true;try{f.run();throw std::runtime_error("missing bounded append failure");}catch(const s::UnsupportedInput&){check(f.effects.reserved==(count==-1?30U:32U)&&f.effects.appended==(count==-1?UINT64_MAX-1:UINT64_MAX)&&!f.effects.outputs&&!f.effects.destroyed,"signed count extension/wrapping preserved without huge allocation or invented cleanup");}}
}
void failures(){
    {Fixture f;f.parse(request("GetConfig"));f.effects.effects.accept=false;reject(f);check(f.effects.constructed==1&&!f.effects.outputs&&!f.effects.destroyed,"false handler has no invented normal printer cleanup");}
    for(const auto stage:{"name","find","printer","handler","reserve","append","output","free-scratch","destroy-printer"}){Fixture f;f.parse(request("GetConfig"));f.effects.hook=[&](auto name){if(name==stage)throw native_message_test::Failure{44};};try{f.run();throw std::runtime_error("missing injected failure");}catch(const native_message_test::Failure& e){check(e.code==44&&!f.effects.destroyed,"throw prefix retained; no invented destructor or rollback");const bool committed=std::string_view(stage)=="free-scratch"||std::string_view(stage)=="destroy-printer";check(f.effects.outputs==unsigned(committed),"output commit precedes cleanup failures only");}}
    {Fixture f;f.parse(request("GetConfig"));try{s::dispatch_native_032d00(f.locals.scratch,0x120f0,f.native.locals.document,f.context);throw std::runtime_error("alias accepted");}catch(const s::UnsupportedInput&){check(!f.effects.prepared,"bounded automatic scratch alias guard before effects");}}
}
}
int main(){try{commands();shapes();live();failures();std::cout<<"PASS: "<<checks<<" native dispatch checks;39 commands, validation, live callbacks, signed count/reloads, output/free order and failure prefixes; native lower providers remain open\n";}catch(const std::exception& e){std::cerr<<"FAIL after "<<checks<<" checks: "<<e.what()<<'\n';return 1;}catch(...){std::cerr<<"FAIL: unexpected terminal\n";return 1;}}
